export type CustomerStatus = "pending" | "more_info" | "approved" | "rejected";

export type Currency = "BRL" | "USD" | "EUR";

export type ProductStatus = "draft" | "published" | "archived";

export interface ProductImage {
  id: string;
  storagePath: string;
  position: number;
}

/** A concrete size+color combination generated by the variant matrix trigger. */
export interface Variant {
  id: string;
  size: string;
  sizeBr?: string | null;
  sizeUs?: string | null;
  sizeEu?: string | null;
  color: string;
  sku: string;
  stock: number;
}

/** Precomputed prices — only returned by get_priced_product/get_priced_catalog for approved customers. */
export interface ProductPricing {
  priceBrl: number | null;
  priceUsd: number | null;
  priceEur: number | null;
}
